require_once __DIR__.'/includes/functions.php';$where=[];$params=[];$q=trim($_GET['q']??'');if($q!==''){$where[]='(p.name LIKE ? OR p.brand LIKE ? OR c.category_name LIKE ?)';array_push($params,"%$q%","%$q%","%$q%");}foreach(['brand'=>['Samsung','Apple'],'condition'=>['New','Used']] as $field=>$allowed)if(in_array($_GET[$field]??'',$allowed,true)){$where[]="p.$field=?";$params[]=$_GET[$field];}if(($category=filter_input(INPUT_GET,'category',FILTER_VALIDATE_INT))){$where[]='p.category_id=?';$params[]=$category;}if(($storage=trim($_GET['storage']??''))!==''){$where[]='p.storage=?';$params[]=$storage;}if(($_GET['availability']??'')==='in')$where[]='p.stock>0';if(($max=filter_input(INPUT_GET,'max',FILTER_VALIDATE_INT))&&$max>0){$where[]='p.price<=?';$params[]=$max;}$sort=($_GET['sort']??'')==='low'?'p.price ASC':(($_GET['sort']??'')==='high'?'p.price DESC':'p.created_at DESC');$sql='SELECT p.*,c.category_name,(SELECT image_path FROM product_images WHERE product_id=p.id ORDER BY id LIMIT 1) image FROM products p LEFT JOIN categories c ON c.id=p.category_id'.($where?' WHERE '.implode(' AND ',$where):'')." ORDER BY $sort LIMIT 48";try{$s=db()->prepare($sql);$s->execute($params);$products=$s->fetchAll();$categories=db()->query('SELECT * FROM categories ORDER BY brand,category_name')->fetchAll();$storages=db()->query('SELECT DISTINCT storage FROM products ORDER BY storage')->fetchAll(PDO::FETCH_COLUMN);}catch(Throwable $e){$products=[];$categories=[];$storages=[];$database_unavailable=true;}$page_title='Genuine Samsung & iPhone Devices';require 'includes/header.php';
