se_unavailable)):?><div class="empty">Import <code>database.sql</code> after starting MySQL to display the catalogue.</div><?php elseif(!$products):?><div class="empty">No phones match these filters. <a href="index.php">Clear filters</a>.</div><?php else:?><div class="products-grid"><?php foreach($products as $p):?><article class="product-card"><a class="product-image" href="product-details.php?id=<?=$p['id']?>"><img loading="lazy" src="<?=image_url($p['image'])?>" alt="<?=e($p['brand'].' '.$p['name'])?>"></a><div class="product-info"><span class="badge <?=strtolower($p['brand'])?>"><?=e($p['brand'])?></span><h3><a href="product-details.php?id=<?=$p['id']?>"><?=e($p['name'])?></a></h3><p><?=e($p['storage'])?> · <?=e($p['condition'])?> · <?=e($p['quality'])?></p><strong><?=money($p['price'])?></strong><span class="stock <?=$p['stock']>0?'in':'out'?>"><?=$p['stock']>0?$p['stock'].' in stock':'Out of stock'?></span><div class="card-actions"><a class="button dark-button" href="product-details.php?id=<?=$p['id']?>">View details</a><?php if($p['stock']>0):?><form method="post" action="cart.php"><input type="hidden" name="csrf" value="<?=csrf_token()?>"><input type="hidden" name="product_id" value="<?=$p['id']?>"><button class="button primary" name="action" value="add">Add to cart</button></form><?php endif?></div></div></article><?php endforeach?></div><?php endif?></div></section><section class="section dark" id="about"><div class="container split"><div><p class="eyebrow light">The Collins M standard</p><h2>Find the phone that <em>fits your life.</em></h2><p>Genuine Samsung Galaxy and Apple iPhone devices in Nairobi—new and carefully selected used options.</p></div></div></section><section class="section contact" id="contact"><div class="container"><p class="eyebrow">Let’s get you connected</p><h2>Ready for an upgrade?</h2><p>Ask about a model, colour, storage, or current price.</p><a class="button whatsapp" target="_blank" rel="noopener" href="<?=e(whatsapp_url())?>"><i